        int cur = 0;
        for (int j = 0; j < n; ++j) {
            if (arr[j] - arr[i] <= d && arr[j] - arr[i] >= 0) {
                ++cur;
            }
        }
        maxgrp = std::max(maxgrp, cur);
    }

    std::printf("%d\n", n - maxgrp);
    return 0;
}

